/**
 * Image storage abstraction.
 *
 * Features call `getStorage()` and only use the `StorageDriver` interface, so an
 * S3-compatible driver can replace the local filesystem driver later without
 * touching feature code. Keys are always generated by the application
 * (e.g. `originals/img_xxx.png`) and validated, never derived from user input.
 */
import fs from "node:fs/promises";
import path from "node:path";
import { getConfig } from "../config";

export interface StorageDriver {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
  exists(key: string): Promise<boolean>;
  /** File size in bytes, or null if missing. */
  size(key: string): Promise<number | null>;
  /** Byte range [start, end] inclusive — used to stream video with HTTP Range requests. */
  getRange(key: string, start: number, end: number): Promise<Buffer | null>;
  /** Total bytes and file count, for the settings page. */
  usage(): Promise<{ bytes: number; files: number }>;
}

const KEY_PATTERN = /^(originals|previews|thumbs)\/img_[0-9a-z]{6,32}\.(png|jpg|webp|mp4)$/;

export function assertValidKey(key: string) {
  if (!KEY_PATTERN.test(key)) throw new Error("Invalid storage key");
}

class LocalStorageDriver implements StorageDriver {
  constructor(private readonly root: string) {}

  private resolve(key: string) {
    assertValidKey(key);
    const full = path.resolve(/*turbopackIgnore: true*/ this.root, key);
    // Defense in depth against traversal even though keys are pattern-checked.
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Invalid storage key");
    return full;
  }

  async put(key: string, data: Buffer) {
    const full = this.resolve(key);
    await fs.mkdir(path.dirname(full), { recursive: true });
    const tmp = `${full}.${process.pid}.tmp`;
    await fs.writeFile(tmp, data);
    await fs.rename(tmp, full);
  }

  async get(key: string) {
    try {
      return await fs.readFile(this.resolve(key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    }
  }

  async delete(key: string) {
    await fs.rm(this.resolve(key), { force: true });
  }

  async exists(key: string) {
    try {
      await fs.access(this.resolve(key));
      return true;
    } catch {
      return false;
    }
  }

  async size(key: string) {
    try {
      return (await fs.stat(this.resolve(key))).size;
    } catch {
      return null;
    }
  }

  async getRange(key: string, start: number, end: number) {
    let handle: fs.FileHandle | null = null;
    try {
      handle = await fs.open(this.resolve(key), "r");
      const length = end - start + 1;
      const buf = Buffer.alloc(length);
      const { bytesRead } = await handle.read(buf, 0, length, start);
      return buf.subarray(0, bytesRead);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    } finally {
      await handle?.close();
    }
  }

  async usage() {
    let bytes = 0;
    let files = 0;
    for (const dir of ["originals", "previews", "thumbs"]) {
      try {
        const entries = await fs.readdir(path.join(/*turbopackIgnore: true*/ this.root, dir), { withFileTypes: true });
        for (const entry of entries) {
          if (!entry.isFile()) continue;
          const stat = await fs.stat(path.join(/*turbopackIgnore: true*/ this.root, dir, entry.name));
          bytes += stat.size;
          files += 1;
        }
      } catch {
        // directory does not exist yet
      }
    }
    return { bytes, files };
  }
}

let driver: StorageDriver | null = null;
let driverRoot: string | null = null;

export function getStorage(): StorageDriver {
  const { storageDir } = getConfig();
  if (!driver || driverRoot !== storageDir) {
    driver = new LocalStorageDriver(storageDir);
    driverRoot = storageDir;
  }
  return driver;
}
